in vec3 aPosition;
in vec3 aVelocity;
in float aLife;

out vec3 vPosition;
out vec3 vVelocity;
out float vLife;

uniform float uDeltaTime;
uniform vec3 uGravity;
uniform float uDrag;

void main() {
    // Euler integration
    vec3 acceleration = uGravity;
    vec3 newVelocity = aVelocity + acceleration * uDeltaTime;
    newVelocity *= (1.0 - uDrag * uDeltaTime);

    vec3 newPosition = aPosition + newVelocity * uDeltaTime;
    float newLife = aLife - uDeltaTime;

    // Respawn dead particles
    if (newLife <= 0.0) {
        newPosition = emitterPosition();
        newVelocity = randomVelocity();
        newLife = randomLife();
    }

    vPosition = newPosition;
    vVelocity = newVelocity;
    vLife = newLife;
}

// Specify output varyings before linking
gl.transformFeedbackVaryings(
    simulationProgram,
    ['vPosition', 'vVelocity', 'vLife'],
    gl.INTERLEAVED_ATTRIBS
);
gl.linkProgram(simulationProgram);

// Create transform feedback object
const transformFeedback = gl.createTransformFeedback();

// During render loop:
gl.bindTransformFeedback(gl.TRANSFORM_FEEDBACK, transformFeedback);
gl.bindBufferBase(gl.TRANSFORM_FEEDBACK_BUFFER, 0, writeBuffer);
gl.beginTransformFeedback(gl.POINTS);
gl.enable(gl.RASTERIZER_DISCARD); // Skip fragment stage
gl.drawArrays(gl.POINTS, 0, particleCount);
gl.disable(gl.RASTERIZER_DISCARD);
gl.endTransformFeedback();
